		public void store(OT obj, DBRecord record) {
			try {
				doStore(obj, record);
			}
			catch (Exception e) when (e is IllegalArgumentException or IllegalAccessException) {
				throw new AssertionError(e);
			}
		}

		/* @Override */
		public void load(OT obj, DBRecord record) {
			try {
				doLoad(obj, record);
			}
			catch (Exception e) when (e is IllegalArgumentException or IllegalAccessException) {
				throw new AssertionError(e);
			}
		}

		/* @Override */
		public Class<VT> getValueType() {
			return valueType;
		}

		/* @Override */
		public Class<OT> getObjectType() {
			return objectType;
		}

		/* @Override */
		public Class<FT> getFieldType() {
