		 *
		 * @param <E> the type of elements
		 * @param <T> the type of the value, i.e., would be {@code E[]}, except we want {@link E} to
		 *            be primitive.
		 */
		class ArrayPrimitiveCodec<E, T> : AbstractPrimitiveCodec<T> {
			protected PrimitiveCodec<E> elemCodec;
			protected Class<E> elemClass;

			public ArrayPrimitiveCodec(Class<T> valueClass, PrimitiveCodec<E> elemCodec) : base(valueClass)
    {
				System.Diagnostics.Debug.Assert(valueClass.isArray();
				this.elemCodec = elemCodec;
				this.elemClass = elemCodec.getValueClass();
			}

			/* @Override */
			public T decode(ByteBuffer buffer) {
				List<E> result = new();
				while (buffer.hasRemaining()) {
					result.add(elemCodec.decode(buffer));
				}
				int size = result.size();
				object arr = Array.newInstance(valueClass.getComponentType(), size);
				for (int i = 0; i < size; i++) {
					Array.set(arr, i, result.get(i));
				}
				return valueClass.cast(arr);
			}

			/* @Override */
			public void encode(ByteBuffer buffer, T value) {
				int len = Array.getLength(value);
				for (int i = 0; i < len; i++) {
					elemCodec.encode(buffer, elemClass.cast(Array.get(value, i)));
				}
			}
		}

		/**
		 * An implementation of an array codec, using its element codec, where elements are objects
		 * 
		 * @param <E> the type of elements
		 */
		class ArrayObjectCodec<E>, ArrayPrimitiveCodec<E, E[]> {
			/* @SuppressWarnings("unchecked") */
			public ArrayObjectCodec(PrimitiveCodec<E> elemCodec) : base((Class<E[]>) Array.newInstance(elemCodec.getValueClass(), 0).GetType(),
					elemCodec)
    {
			}
		}

		/**
		 * A codec which encodes length-value, using the (unbounded) codec for value
		 */
		class LengthBoundCodec<T> : AbstractPrimitiveCodec<T> {
			protected PrimitiveCodec<T> unbounded);

			public LengthBoundCodec(PrimitiveCodec<T> unbounded) : base(unbounded.getValueClass())
    {
				this.unbounded = unbounded;
			}

			/* @Override */
			public T decode(ByteBuffer buffer) {
				int length = buffer.getInt();
				int oldLimit = buffer.limit();
				try {
					buffer.limit(buffer.position() + length);
					return unbounded.decode(buffer);
				}
				finally {
					buffer.limit(oldLimit);
				}
			}

			/* @Override */
			public void encode(ByteBuffer buffer, T value) {
				int lenPos = buffer.position();
				buffer.putInt(0);
				int startPos = buffer.position();
				unbounded.encode(buffer, value);
				int endPos = buffer.position();
				buffer.putInt(lenPos, endPos - startPos);
			}
		}

		/*
		 * WARNING: Careful changing the order of these declarations, as this will change the
		 * selectors. Doing so would require a schema version bump of any table using the
		 * {@link VariantDBFieldCodec}.
		 */
		/** Codec for {@code boolean} */
		PrimitiveCodec<Boolean> BOOL = new(typeof(Boolean),
			buf => buf.get() != 0, (buf, b) => buf.put((byte) (b ? 1 : 0)));
		/** Codec for {@code byte} */
		PrimitiveCodec<Byte> BYTE =
			new(typeof(Byte), ByteBuffer.get, ByteBuffer.put);
		/** Codec for {@code char} */
		PrimitiveCodec<Character> CHAR =
			new(typeof(Character), ByteBuffer.getChar, ByteBuffer.putChar);
		/** Codec for {@code short} */
		PrimitiveCodec<Short> SHORT =
			new(typeof(Short), ByteBuffer.getShort, ByteBuffer.putShort);
		/** Codec for {@code int} */
		PrimitiveCodec<Integer> INT =
			new(typeof(Integer), ByteBuffer.getInt, ByteBuffer.putInt);
		/** Codec for {@code long} */
		PrimitiveCodec<Long> LONG =
			new(typeof(Long), ByteBuffer.getLong, ByteBuffer.putLong);
		/** Codec for {@link String} */
		PrimitiveCodec<string> STRING = new _Anon_AbstractPrimitiveCodec_1(typeof(string));
		/** Codec for {@code boolean[]} */
		PrimitiveCodec<bool[]> BOOL_ARR = new(bool[].class, BOOL);
		/** Codec for {@code byte[]} */
		PrimitiveCodec<byte[]> BYTE_ARR = new _Anon_AbstractPrimitiveCodec_2(byte[].class);
		/** Codec for {@code char[]} */
		PrimitiveCodec<char[]> CHAR_ARR = new(char[].class, CHAR);
		/** Codec for {@code short[]} */
		PrimitiveCodec<short[]> SHORT_ARR = new(short[].class, SHORT);
		/** Codec for {@code int[]} */
		PrimitiveCodec<int[]> INT_ARR = new(int[].class, INT);
		/** Codec for {@code long[]} */
		PrimitiveCodec<long[]> LONG_ARR = new(long[].class, LONG);
		/** Codec for {@code String[]} */
		PrimitiveCodec<string[]> STRING_ARR =
			new(new(STRING));
		PrimitiveCodec<RecAddress> ADDRESS = new _Anon_AbstractPrimitiveCodec_3(typeof(RecAddress));
		PrimitiveCodec<RecRange> RANGE = new _Anon_AbstractPrimitiveCodec_4(typeof(RecRange));

		// TODO: No floats?
		Map<Byte, PrimitiveCodec<object>> CODECS_BY_SELECTOR = Stream
				.of(BOOL, BYTE, CHAR, SHORT, INT, LONG, STRING, BOOL_ARR, BYTE_ARR, CHAR_ARR,
					SHORT_ARR, INT_ARR, LONG_ARR, STRING_ARR, ADDRESS, RANGE)
				.collect(Collectors.toMap(c => c.getSelector(), c => c));
		Map<Class<object>, PrimitiveCodec<object>> CODECS_BY_CLASS = CODECS_BY_SELECTOR.values()
				.stream()
				.collect(Collectors.toMap(c => c.getValueClass(), c => c));

		/**
		 * Get the codec for the given type
		 * 
		 * @param <T> the type
		 * @param cls the class describing {@link T}
		 * @return the codec
		 * @throws IllegalArgumentException if the type is not supported
		 */static PrimitiveCodec<T> getCodec<T>(Class<T> cls) {
			/* @SuppressWarnings("unchecked") */
			PrimitiveCodec<T> obj = (PrimitiveCodec<T>) CODECS_BY_CLASS.get(cls);
			if (obj == null) {
				throw new IllegalArgumentException("No variant codec for class " + cls);
			}
			return obj;
		}

		/**
		 * Get the codec for the given selector
		 * 
		 * @param sel the selector
		 * @return the codec
		 * @throws IllegalArgumentException if the selector is unknown
		 */
		static PrimitiveCodec<object> getCodec(byte sel) {
			PrimitiveCodec<object> obj = CODECS_BY_SELECTOR.get(sel);
			if (obj == null) {
				throw new IllegalArgumentException("No variant codec with selector " + sel);
			}
			return obj;
		}
	}

	/**
	 * A custom codec for field of "variant" type
	 * 
	 * <p>
	 * This is suitable for use on fields of type {@link Object}; however, only certain types can
	 * actually be encoded. The encoding uses a 1-byte type selector followed by the byte-array
	 * encoded value.
	 */
	public static class VariantDBFieldCodec<OT> : AbstractDBFieldCodec<object, OT, BinaryField> where OT : DBAnnotatedObject {
		public VariantDBFieldCodec(Class<OT> objectType, Field field, int column) : base(typeof(object), objectType, typeof(BinaryField), field, column)
    {
		}

		protected PrimitiveCodec<object> getPrimitiveCodec(Class<object> cls) {
			return PrimitiveCodec.getCodec(cls);
		}

		protected PrimitiveCodec<object> getPrimitiveCodec(OT obj, byte sel) {
			return PrimitiveCodec.getCodec(sel);
		}

		protected byte[] encode(object value) {
			if (value == null) {
				return null;
			}
			/* @SuppressWarnings("unchecked") */
			PrimitiveCodec<object> codec =
				(PrimitiveCodec<object>) getPrimitiveCodec(value.GetType());
			ByteBuffer buf = ByteBuffer.allocate(1024);
			while (true) {
				try {
					buf.clear();
					buf.put(codec.getSelector());
					codec.encode(buf, value);
					buf.flip();
					byte[] result = new byte[buf.remaining()];
					buf.get(result);
					return result;
				}
				catch (BufferOverflowException e) {
					buf = ByteBuffer.allocate(buf.capacity() * 2);
				}
			}
		}

		protected object decode(OT obj, byte[] enc) {
			if (enc == null) {
				return null;
			}
			ByteBuffer buf = ByteBuffer.wrap(enc);
			PrimitiveCodec<object> codec = getPrimitiveCodec(obj, buf.get());
			return codec.decode(buf);
		}

		/* @Override */
		public void store(object value, BinaryField f) {
			f.setBinaryData(encode(value));
		}

		/* @Override */
		protected void doStore(OT obj, DBRecord record)
    {
			record.setBinaryData(column, encode(getValue(obj)));
		}

		/* @Override */
		protected void doLoad(OT obj, DBRecord record)
    {
			setValue(obj, decode(obj, record.getBinaryData(column)));
		}
	}

	/**
	 * The information needed to construct a {@link Table} and store objects into it
	 *
	 * @param <OT> the type of object stored in the table
	 */
	private static class TableInfo<OT> where OT : DBAnnotatedObject {
		public Schema schema;
		public int[] indexColumns;
		public List<DBFieldCodec<object, OT,object>> codecs;

		/**
		 * Derive the table information
		 * 
		 * @param objectType the class of objects being described
		 * @param schemaVersion the schema version as given in
		 *            {@link DBAnnotatedObjectInfo#version()}
		 * @param fieldsByColumnName the class fields by user-defined column name
		 * @param indexFields the fields selected for table indexes
		 * @param sparseFields the fields selected for sparse storage
		 */
		TableInfo(Class<OT> objectType, int schemaVersion, Map<string, Field> fieldsByColumnName,
				Collection<Field> indexFields, Collection<Field> sparseFields) {
			codecs = new(fieldsByColumnName.size());
			List<Integer> indexCols = new(indexFields.size());
			SchemaBuilder builder = new SchemaBuilder();
			builder.version(schemaVersion);
			builder.keyField("Key", typeof(LongField));

			foreach (Map.Entry<string, Field> ent in fieldsByColumnName.entrySet()) {
				int next = builder.fieldCount();
				Field field = ent.getValue();
				DBFieldCodec<object, OT,object> codec = makeCodec(objectType, field, next);
				if (indexFields.contains(field)) {
					indexCols.add(next);
				}
				codecs.add(codec);
				builder.field(ent.getKey(), codec.getFieldType(), sparseFields.contains(field));
			}
			schema = builder.build();

			indexColumns = SchemaBuilder.toIntArray(indexCols);
		}

		/**
		 * Initialize the static {@link DBObjectColumn} fields marked with {@link DBAnnotatedColumn}
		 * 
		 * @param objectType the clas of objects being described
		 * @param numbersByName the assigned column numbers by user-defined name
		 */
		void writeColumnNumbers(Class<DBAnnotatedObject> objectType,
				Map<string, Integer> numbersByName) {
			Class<object> superType = objectType.getSuperclass();
			if (typeof(DBAnnotatedObject).isAssignableFrom(superType)) {
				writeColumnNumbers(superType.asSubclass(typeof(DBAnnotatedObject)), numbersByName);
			}
			foreach (Field f in objectType.getDeclaredFields()) {
				DBAnnotatedColumn annotation = f.getAnnotation(typeof(DBAnnotatedColumn));
				if (annotation == null) {
					continue;
				}
				int mod = f.getModifiers();
				if (!Modifier.isStatic(mod)) {
					throw new IllegalArgumentException(
						"@" + typeof(DBAnnotatedColumn).getSimpleName() +
							" fields must be static. Got " + f);
				}
				if (f.getType() != typeof(DBObjectColumn)) {
					throw new IllegalArgumentException(
						"@" + typeof(DBAnnotatedColumn).getSimpleName() + " fields must be " +
							typeof(DBObjectColumn).getSimpleName() + " type. Got " + f);
				}

				string name = annotation.value();

				Integer columnNumber = numbersByName.get(name);
				if (columnNumber == null) {
					throw new IllegalArgumentException("Cannot find column '" + name + "' for @" +
						typeof(DBAnnotatedColumn).getSimpleName() + " on " + f);
				}

				f.setAccessible(true);
				try {
					DBObjectColumn already = (DBObjectColumn) f.get(null);
					if (already == null) {
						f.set(null, DBObjectColumn.get(columnNumber.intValue()));
					}
					else if (already.columnNumber != columnNumber.intValue()) {
						throw new AssertionError();
					}
				}
				catch (IllegalAccessException e) {
					throw new AssertionError(e);
				}
			}
		}

		/**
		 * Initialize the static {@link DBObjectColumn} fields marked with {@link DBAnnotatedColumn}
		 * 
		 * @param objectType the clas of objects being described
		 */
		void writeColumnNumbers(Class<DBAnnotatedObject> objectType) {
			Map<string, Integer> numbersByName = new();
			string[] names = schema.getFieldNames();
			for (int i = 0; i < names.length; i++) {
				numbersByName.put(names[i], i);
			}
			writeColumnNumbers(objectType, numbersByName);
		}
	}

	/**
	 * A cache of derived table information by class
	 */
	private static readonly Map<Class<DBAnnotatedObject>, TableInfo<object>> INFO_MAP =
		new();

	/**
	 * Get a built-in codec for a field of the given type
	 * 
	 * @param type the type
	 * @return the built-in codec
	 * @throws NoDefaultCodecException if there is no built-in codec for the field
	 */
	private static Class<object> getDefaultCodecClass(Class<object> type) {
		if (type == typeof(bool) || type == typeof(Boolean)) {
			return typeof(BooleanDBFieldCodec);
		}
		if (type == typeof(byte) || type == typeof(Byte)) {
			return typeof(ByteDBFieldCodec);
		}
		if (type == typeof(short) || type == typeof(Short)) {
			return typeof(ShortDBFieldCodec);
		}
		if (type == typeof(int) || type == typeof(Integer)) {
			return typeof(IntDBFieldCodec);
		}
		if (type == typeof(long) || type == typeof(Long)) {
			return typeof(LongDBFieldCodec);
		}
		if (type == typeof(string)) {
			return typeof(StringDBFieldCodec);
		}
		if (type == byte[].class) {
			return typeof(ByteArrayDBFieldCodec);
		}
		// TODO: Other primitive arrays?
		if (type == long[].class) {
			return typeof(LongArrayDBFieldCodec);
		}
		if (typeof(Enum).isAssignableFrom(type)) {
			return typeof(EnumDBByteFieldCodec);
		}
		throw new NoDefaultCodecException(
			type + " does not have a default codec. Please specify a codec.");
	}

	/**
	 * Construct the codec for the given field
	 * 
	 * <p>
	 * This adheres to the custom codec, if specified on the fields annotation.
	 * 
	 * @param <OT> the type of objects being described
	 * @param objectType the class describing {@link OT}
	 * @param field the field to encode and decode
	 * @param column the column number in the record
	 * @return the codec
	 * @throws IllegalArgumentException if the selected codec's constructor does not have the
	 *             required signature
	 */
	/* @SuppressWarnings({ "unchecked" }) */
	private static DBFieldCodec<object, OT,object> makeCodec<OT>/* where OT : DBAnnotatedObject */(
			Class<OT> objectType, Field field, int column)
    {
		Class<object> type = field.getType();
		DBAnnotatedField annotation = field.getAnnotation(typeof(DBAnnotatedField));
		System.Diagnostics.Debug.Assert(annotation != null;
		Class<object> codecCls = annotation.codec();
		if (codecCls == typeof(DefaultCodec)) {
			codecCls = getDefaultCodecClass(type);
		}
		try {
			Constructor<object> codecCons = codecCls.getConstructor(typeof(Class), typeof(Field), typeof(int));
			return (DBFieldCodec<object, OT,object>) codecCons.newInstance(objectType, field, column);
		}
		catch (Exception e) when (e is NoSuchMethodException or SecurityException or InstantiationException or IllegalAccessException) {
			throw new AssertionError(e);
		}
		catch (InvocationTargetException e) {
			Throwable cause = e.getCause();
			if (cause is RuntimeException) {
				throw (RuntimeException) cause;
			}
			throw new RuntimeException(cause); // TODO: What exception type for this?
		}
	}

	/**
	 * Get the table information for the given class
	 * 
	 * @param <T> the type of objects to store in a table
	 * @param cls the class describing {@link T}
	 * @return the table information
	 */
	/* @SuppressWarnings("unchecked") */
	private static TableInfo<T> getInfo<T>/* where T, DBAnnotatedObject */(Class<T> cls) {
		lock (INFO_MAP) {
			return (TableInfo<T>) INFO_MAP.computeIfAbsent(cls,
				DBCachedObjectStoreFactory.buildInfo));
		}
	}

	/**
	 * Get the codecs for the given class
	 * 
	 * @param <OT> the type of objects to store in the table
	 * @param objectType the class describing {@link OT}
	 * @return the codecs, in column order
	 */static List<DBFieldCodec<object, OT,object>> getCodecs<OT>/* where OT : DBAnnotatedObject */(
			Class<OT> objectType) {
		return getInfo(objectType).codecs;
	}

	/**
	 * The non-cached implementation of {@link #getInfo(Class)}
	 */private static TableInfo<OT> buildInfo<OT>/* where OT : DBAnnotatedObject */(Class<OT> objectType) {
		DBAnnotatedObjectInfo info = objectType.getAnnotation(typeof(DBAnnotatedObjectInfo));
		if (info == null) {
			throw new IllegalArgumentException(
				typeof(DBAnnotatedObject).getSimpleName() + " " + objectType.getName() +
					" must have @" + typeof(DBAnnotatedObjectInfo).getSimpleName() + " annotation");
		}

		Map<string, Field> fields = new();
		List<Field> indexFields = new();
		List<Field> sparseFields = new();
		collectFields(objectType, fields, indexFields, sparseFields);

		TableInfo<OT> tableInfo =
			new(objectType, info.version(), fields, indexFields, sparseFields);
		tableInfo.writeColumnNumbers(objectType);

		return tableInfo;
	}

	/**
	 * Collect the fields of the given class, recursively, starting with its super class
	 * 
	 * @param cls the class
	 * @param fields a map to receive the fields
	 * @param indexFields a list for receiving fields to be indexed
	 * @param sparseFields a list for receiving fields to have sparse storage
	 */
	private static void collectFields(Class<object> cls, Map<string, Field> fields,
			List<Field> indexFields, List<Field> sparseFields) {
		Class<object> superclass = cls.getSuperclass();
		if (superclass != null) {
			collectFields(superclass, fields, indexFields, sparseFields);
		}
		foreach (Field f in cls.getDeclaredFields()) {
			DBAnnotatedField annotation = f.getAnnotation(typeof(DBAnnotatedField));
			if (annotation == null) {
				continue;
			}
			int mod = f.getModifiers();
			if (Modifier.isStatic(mod) || Modifier.isFinal(mod)) {
				throw new IllegalArgumentException(
					typeof(DBAnnotatedField).getSimpleName() + " must be non-static and non-final");
			}
			f.setAccessible(true);
			Field old = fields.put(annotation.column(), f);
			if (old != null) {
				indexFields.remove(old);
			}
			if (annotation.indexed()) {
				indexFields.add(f);
			}
			if (annotation.sparse()) {
				sparseFields.add(f);
			}
		}
	}

	private DBHandle handle;
	private DBCachedDomainObjectAdapter adapter;

	/**
	 * Construct an object store factory
	 * 
	 * @param adapter the object whose tables to manage
	 */
	public DBCachedObjectStoreFactory(DBCachedDomainObjectAdapter adapter) {
		this.handle = adapter.getDBHandle();
		this.adapter = adapter;
	}

	/**
	 * Get or create the table needed to store objects of the given class
	 * 
	 * <p>
	 * See {@link #getOrCreateCachedStore(String, Class, DBAnnotatedObjectFactory, boolean)}
	 * 
	 * @param name the table name
	 * @param cls the type of objects to store
	 * @param upgradable true if {@link VersionException}s should be marked upgradable when an
	 *            existing table's version is earlier than expected
	 * @return the table
	 * @throws IOException if there's an issue accessing the database
	 * @throws VersionException if an existing table's version does not match that expected
	 */
	public Table getOrCreateTable(string name, Class<DBAnnotatedObject> cls,
			bool upgradable)
    {
		// TODO: System of upgraders
		Table table = handle.getTable(name);
		TableInfo<object> info = getInfo(cls);
		if (table == null) {
			table = handle.createTable(name, info.schema, info.indexColumns);
		}
		int tableVersion = table.getSchema().getVersion();
		int latestVersion = info.schema.getVersion();
		if (tableVersion != latestVersion) {
			throw new VersionException(upgradable && tableVersion < latestVersion);
		}
		return table;
	}

	/**
	 * Get or create a cached store of objects of the given class
	 * 
	 * @param <T> the type of objects in the store
	 * @param tableName the table name
	 * @param cls the class describing {@link T}
	 * @param factory the object's constructor, usually a method reference or lambda
	 * @param upgradable true if {@link VersionException}s should be marked upgradable when an
	 *            existing table's version is earlier than expected
	 * @return the table
	 * @throws IOException if there's an issue accessing the database
	 * @throws VersionException if an existing table's version does not match that expected
	 */public DBCachedObjectStore<T> getOrCreateCachedStore<T>/* where T : DBAnnotatedObject */(
			string tableName, Class<T> cls, DBAnnotatedObjectFactory<T> factory, bool upgradable)
    {
		Table table = getOrCreateTable(tableName, cls, upgradable);
		return new(adapter, cls, factory, table);
	}

	internal class _Anon_AbstractPrimitiveCodec_1 : AbstractPrimitiveCodec<>
	{
		public _Anon_AbstractPrimitiveCodec_1() : @base(typeof(string)) {}

			Charset cs = Charset.forName("UTF-8");

			/* @Override */
			public string decode(ByteBuffer buffer) {
				CharsetDecoder dec = cs.newDecoder();
				try {
					CharBuffer cb = dec.decode(buffer);
					return cb.toString();
				}
				catch (CharacterCodingException e) {
					throw new AssertionError(e);
				}
			}

			/* @Override */
			public void encode(ByteBuffer buffer, string value) {
				CharsetEncoder enc = cs.newEncoder();
				enc.encode(CharBuffer.wrap(value), buffer, true);
			}
		
	}


	internal class _Anon_AbstractPrimitiveCodec_2 : AbstractPrimitiveCodec<>
	{
		public _Anon_AbstractPrimitiveCodec_2() : @base(byte[].class) {}

			/* @Override */
			public byte[] decode(ByteBuffer buffer) {
				byte[] result = new byte[buffer.remaining()];
				buffer.get(result);
				return result;
			}

			/* @Override */
			public void encode(ByteBuffer buffer, byte[] value) {
				buffer.put(value);
			}
		
	}


	internal class _Anon_AbstractPrimitiveCodec_3 : AbstractPrimitiveCodec<>
	{
		public _Anon_AbstractPrimitiveCodec_3() : @base(typeof(RecAddress)) {}

			/* @Override */
			public RecAddress decode(ByteBuffer buffer) {
				int spaceId = buffer.getInt();
				long offset = buffer.getLong();
				return new RecAddress(spaceId, offset);
			}

			/* @Override */
			public void encode(ByteBuffer buffer, RecAddress value) {
				buffer.putInt(value.spaceId);
				buffer.putLong(value.offset);
			}
		
	}


	internal class _Anon_AbstractPrimitiveCodec_4 : AbstractPrimitiveCodec<>
	{
		public _Anon_AbstractPrimitiveCodec_4() : @base(typeof(RecRange)) {}

			/* @Override */
			public RecRange decode(ByteBuffer buffer) {
				int spaceId = buffer.getInt();
				long min = buffer.getLong();
				long max = buffer.getLong();
				return new RecRange(spaceId, min, max);
			}

			/* @Override */
			public void encode(ByteBuffer buffer, RecRange value) {
				buffer.putInt(value.spaceId);
				buffer.putLong(value.min);
				buffer.putLong(value.max);
			}
		
	}

}
